<script setup lang="ts">
import PasswordInput from './PasswordInput.vue';
import { notify, useFeedback } from '../services/feedback';
import { onBeforeUnmount, onMounted, ref } from 'vue';
import { api } from '../services/api';
import type { Profile, User } from '../types';
import ConfirmDialog from './ConfirmDialog.vue';
import HazardAchievements from './HazardAchievements.vue';
import SocialLoginButtons from './SocialLoginButtons.vue';
const connected = ref<string[]>([]); const linkPassword = ref('');
async function loadConnections() { try { connected.value = (await api<{ providers: string[] }>('/api/auth/social/accounts')).providers; } catch { /* The profile request reports connection failures. */ } }
onMounted(() => { void loadConnections(); window.addEventListener('social-authenticated', loadConnections); });
onBeforeUnmount(() => window.removeEventListener('social-authenticated', loadConnections));
const props = defineProps<{ user: User }>(); const emit = defineEmits<{ updated: [user: User] }>();
const profile = ref<Profile>(); const name = ref(props.user.name); const email = ref(props.user.email); const currentPassword = ref(''); const password = ref(''); const passwordConfirmation = ref(''); const confirm = ref(false); const busy = ref(false); const error = ref(''); const saved = ref('');
useFeedback([error], [saved]);
onMounted(async () => { try { profile.value = await api<Profile>('/api/profile'); } catch (e) { error.value = (e as Error).message; } });
async function save() { if (busy.value) return; saved.value = ''; busy.value = true; error.value = ''; try { profile.value = await api<Profile>('/api/profile', { method: 'PATCH', body: JSON.stringify({ name: name.value, email: email.value, ...(password.value ? { current_password: currentPassword.value, password: password.value, password_confirmation: passwordConfirmation.value } : {}) }) }); emit('updated', profile.value.user); password.value = currentPassword.value = passwordConfirmation.value = ''; saved.value = 'Profile updated.'; confirm.value = false; } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><div class="cms-grid"><section class="cms-card"><h2>Your profile</h2><form class="form-body" @submit.prevent="confirm = true"><label>Name<input v-model="name" required minlength="2" maxlength="120"></label><label>Email<input v-model="email" type="email" required></label><template v-if="user.has_password !== false"><h3>Change password (optional)</h3><PasswordInput label="Current password" v-model="currentPassword" autocomplete="current-password" :required="!!password" /><PasswordInput label="New password" v-model="password" autocomplete="new-password" minlength="12" /><PasswordInput label="Confirm new password" v-model="passwordConfirmation" autocomplete="new-password" :required="!!password" /></template><p v-else class="field-help">You sign in with your connected provider. Manage its password through that provider.</p><button class="button primary" type="submit">Save profile</button></form><div class="form-body"><h3>Connected sign-in accounts</h3><p class="field-help">{{ connected.length ? connected.map(p => p === 'google' ? 'Google' : 'Facebook').join(', ') : 'No provider connected yet.' }}</p><template v-if="user.has_password !== false"><p class="field-help">Confirm your MuniAlert password to connect Google or Facebook to this account.</p><PasswordInput label="MuniAlert password" v-model="linkPassword" autocomplete="current-password" maxlength="128" /><SocialLoginButtons mode="link" intent="profile" :current-password="linkPassword" :connected="connected" /></template></div></section><section class="cms-card"><h2>Achievements</h2><p class="field-help">{{ profile?.verified_reports ?? 0 }} verified reports credited to this account. A report counts once after municipal verification.</p><div v-for="badge in profile?.badges || []" :key="badge.id" class="achievement-row" :class="{ locked: !badge.earned }"><span class="achievement-badge" :class="badge.color">{{ badge.name }}</span><div><strong>{{ badge.threshold.toLocaleString() }} verified reports</strong><p>{{ badge.description }}</p><small v-if="badge.reward_type === 'cash'">Cash bonus: ₱{{ Number(badge.cash_amount).toLocaleString('en-PH') }} · municipality fulfillment</small><small v-if="badge.reward_type === 'gift'">Gift: {{ badge.reward_description }} · municipality fulfillment</small><small v-if="!badge.earned">Locked</small><small v-else>Earned</small></div></div></section></div><HazardAchievements :tracks="profile?.hazard_achievements || []" /><ConfirmDialog v-if="confirm" title="Save profile changes?" message="Your name and email will be updated for this account. If you entered a new password, you will use it on your next login." :busy="busy" :error="error" confirm-label="Save profile" @close="confirm = false" @confirm="save" /></template>
